#!/usr/bin/env bash
set -euo pipefail

# Generated by fallow setup-hooks.
# Installer version: 3.6.0
# Local deviations, re-apply after `fallow hooks install` regenerates this
# file: the trusted-checkout block and vp runner, the one-line `--version`,
# the coverage-map block, and the audit's `--base origin/trunk`, each marked
# below.
# Requires bash and jq. On Windows run via git-bash or WSL.
# Blocks Claude Code git commit and git push when fallow audit returns verdict fail.
# Runtime errors fail open with a single stderr notice so skips stay visible.
#
# Version floor (FALLOW_GATE_MIN_VERSION, default 2.85.0). The gate passes
# --gate-marker agent (added in v2.85.0) so Impact can record containment;
# older binaries reject the flag entirely, which would make every audit fail
# open. The floor also covers the older uncommitted-changes inclusion fix
# (aabb8e1b, v2.46.0). Set the env var to the empty string to disable.
# Floor comparison uses `sort -V`; GNU and BSD agree on plain semver but
# diverge on prereleases (BSD sorts `2.48.0-alpha.1` ABOVE `2.48.0`, GNU below).
# If you set a prerelease floor explicitly, verify the behavior on the target OS.

if ! command -v jq >/dev/null 2>&1; then
  echo "fallow-gate: jq not on PATH, skipping audit." >&2
  exit 0
fi

INPUT="$(cat)"
CMD="$(jq -r '.tool_input.command // empty' <<<"$INPUT")"

if ! printf '%s\n' "$CMD" | grep -Eq '(^|[[:space:];|&()])git[[:space:]]+(commit|push)([[:space:]]|$)'; then
  exit 0
fi

# --- Trusted checkouts and the vp runner: local deviation from the generated script ---
# Everything below runs code from the checkout it audits: fallow from its
# node_modules. This gate audits the checkout holding the hook process's
# working directory (it has no target-checkout resolution), and only this project and its
# `.claude/worktrees/*` checkouts are trusted for that; anywhere else (a
# scratch clone, a third-party checkout) is not this gate's to audit, so it
# says so and runs nothing there rather than execute what that tree carries.
# Inside a trusted checkout fallow runs through Vite+ (`vp exec fallow`), which
# resolves the checkout's own pinned copy; the checkout's
# `./node_modules/.bin/fallow` is the fallback where `vp` is not on PATH. The
# generated PATH and `npx --no-install` arms are dropped: the session puts no
# `fallow` on PATH, and the workspace allows no npx invocation.
# `fallow hooks install --target agent --agent claude` overwrites this script
# without asking, so re-apply this block after regenerating.
# The check is made on the checkout's top level (this process's cwd when it
# is not in a work tree), and the audit then runs there, so a commit run from
# a subdirectory is still audited; a worktree is exactly one path component
# under `.claude/worktrees/` and shares the project's git directory, so neither
# a repository nested inside one nor a separate clone at that path is trusted.
GATE_PROJECT="${CLAUDE_PROJECT_DIR:-}"
GATE_PROJECT="${GATE_PROJECT%/}"
# `--show-toplevel` prints a physical path, so compare against the physical
# project path (CLAUDE_PROJECT_DIR may go through a symlink).
if [ -n "$GATE_PROJECT" ]; then
  GATE_PROJECT="$(cd "$GATE_PROJECT" 2>/dev/null && pwd -P || printf '%s' "$GATE_PROJECT")"
fi
GATE_CHECKOUT="$(git rev-parse --show-toplevel 2>/dev/null || printf '%s' "$PWD")"
GATE_TRUSTED=
case "$GATE_CHECKOUT" in
  "$GATE_PROJECT") GATE_TRUSTED=1 ;;
  "$GATE_PROJECT"/.claude/worktrees/*)
    case "${GATE_CHECKOUT#"$GATE_PROJECT"/.claude/worktrees/}" in
      */* | '') ;;
      *)
        # A worktree of this project shares its git directory; a separate
        # clone placed at that path does not.
        GATE_COMMON="$(git -C "$GATE_CHECKOUT" rev-parse --path-format=absolute --git-common-dir 2>/dev/null)"
        GATE_PROJECT_COMMON="$(git -C "$GATE_PROJECT" rev-parse --path-format=absolute --git-common-dir 2>/dev/null)"
        if [ -n "$GATE_COMMON" ] && [ -n "$GATE_PROJECT_COMMON" ] \
          && [ "$(realpath "$GATE_COMMON" 2>/dev/null)" = "$(realpath "$GATE_PROJECT_COMMON" 2>/dev/null)" ]; then
          GATE_TRUSTED=1
        fi
        ;;
    esac
    ;;
esac
if [ -n "$GATE_PROJECT" ] && [ -z "$GATE_TRUSTED" ]; then
  echo "fallow-gate: $GATE_CHECKOUT is not this project or one of its worktrees; not running its tooling, skipping audit." >&2
  exit 0
fi
cd "$GATE_CHECKOUT" || exit 0
if command -v vp >/dev/null 2>&1 && [ -x ./node_modules/.bin/fallow ]; then
  RUNNER=(vp exec fallow)
  BIN_DESC="vp exec fallow ($PWD/node_modules/.bin/fallow)"
elif [ -x ./node_modules/.bin/fallow ]; then
  RUNNER=(./node_modules/.bin/fallow)
  BIN_DESC="./node_modules/.bin/fallow"
else
  echo "fallow-gate: fallow not installed in $PWD (run \`vp install\`), skipping audit." >&2
  exit 0
fi
# --- End trusted checkouts and the vp runner ---

# Local deviation (#580): keep only the first line of `--version`. The npm
# launcher (fallow/scripts/run-binary.js) appends a `verified: ...` line, which
# would otherwise reach the floor check and every message below.
VERSION_RAW="$("${RUNNER[@]}" --version 2>/dev/null | sed -n '1p' || true)"
VERSION="${VERSION_RAW#fallow }"
VERSION="${VERSION%% *}"

MIN_VERSION="${FALLOW_GATE_MIN_VERSION-2.85.0}"
if [ -n "$MIN_VERSION" ] && [ -n "$VERSION" ]; then
  LOWER="$(printf '%s\n%s\n' "$MIN_VERSION" "$VERSION" | sort -V | head -n1)"
  if [ "$LOWER" != "$MIN_VERSION" ]; then
    {
      echo "fallow-gate: blocked: $BIN_DESC is fallow $VERSION, below required $MIN_VERSION."
      echo "fallow-gate: older binaries reject the --gate-marker flag this gate passes"
      echo "fallow-gate: (added in fallow v2.85.0), so the audit cannot run."
      echo "fallow-gate: upgrade the fallow on PATH (e.g. npm install -g fallow@latest or"
      echo "fallow-gate: cargo install fallow-cli), or set FALLOW_GATE_MIN_VERSION= to disable."
    } >&2
    exit 2
  fi
fi

# --- Coverage map: local deviation from the generated script (#580) ---
# The audit reads `coverage/coverage-final.json` (`health.coverage` in
# .fallowrc.json). A fresh `.claude/worktrees/*` checkout has none, and fallow
# then returns a runtime error, which this gate treats as non-blocking, so the
# commit would go through unaudited. Regenerate the map with
# `vp run test:coverage` when it is missing, or older than a source file
# under packages/ or examples/ (dist/, node_modules/ and generated SvelteKit
# output excepted). A failed regeneration is reported and the audit runs on
# whatever map exists (a missing map still fails open, visibly). Set
# FALLOW_GATE_COVERAGE=0 to skip regeneration. The hook's timeout in
# .claude/settings.json allows for the suite.
COVERAGE_MAP=coverage/coverage-final.json
if [ "${FALLOW_GATE_COVERAGE:-1}" != "0" ] && command -v vp >/dev/null 2>&1; then
  COVERAGE_REASON=
  if [ ! -f "$COVERAGE_MAP" ]; then
    COVERAGE_REASON="missing"
  elif [ -n "$(find packages examples \( -name node_modules -o -name dist -o -name build -o -name .svelte-kit \) -prune -o -type f -newer "$COVERAGE_MAP" -print -quit 2>/dev/null)" ]; then
    COVERAGE_REASON="older than a source file"
  fi
  if [ -n "$COVERAGE_REASON" ]; then
    echo "fallow-gate: $COVERAGE_MAP is $COVERAGE_REASON; running \`vp run test:coverage\` before the audit." >&2
    if ! vp run test:coverage >/dev/null 2>&1; then
      echo "fallow-gate: \`vp run test:coverage\` failed; auditing with the coverage map as it stands." >&2
    fi
  fi
fi
# --- End coverage map ---

TMP_JSON="$(mktemp)"
TMP_ERR="$(mktemp)"
cleanup() {
  rm -f "$TMP_JSON" "$TMP_ERR"
}
trap cleanup EXIT

# Local deviation: --base origin/trunk (the default branch is trunk).
if "${RUNNER[@]}" audit --format json --quiet --explain --gate-marker agent --base origin/trunk >"$TMP_JSON" 2>"$TMP_ERR"; then
  STATUS=0
else
  STATUS=$?
fi

VERDICT="$(jq -r '.verdict // empty' <"$TMP_JSON" 2>/dev/null || true)"
IS_ERROR="$(jq -r '.error // false' <"$TMP_JSON" 2>/dev/null || echo false)"

if [ "$VERDICT" = "fail" ]; then
  echo "fallow-gate: blocked by fallow ${VERSION:-unknown} at $BIN_DESC" >&2
  cat "$TMP_JSON" >&2
  exit 2
fi

if [ "$STATUS" -eq 2 ] || [ "$IS_ERROR" = "true" ]; then
  MSG="$(jq -r '.message // empty' <"$TMP_JSON" 2>/dev/null || true)"
  if [ -n "$MSG" ]; then
    echo "fallow-gate: fallow audit runtime error ($MSG), skipping." >&2
  else
    echo "fallow-gate: fallow audit runtime error, skipping." >&2
  fi
  exit 0
fi

if [ "$STATUS" -ne 0 ]; then
  ERR_LINE="$(sed -n '1p' "$TMP_ERR" 2>/dev/null || true)"
  if [ -n "$ERR_LINE" ]; then
    echo "fallow-gate: fallow audit exited $STATUS ($ERR_LINE), skipping." >&2
  else
    echo "fallow-gate: fallow audit exited $STATUS, skipping." >&2
  fi
  exit 0
fi

exit 0
